export const AOE_TYPES = {
  CIRCLE: 'circle',
  CONE: 'cone',
  CUBE: 'cube',
  LINE: 'line',
  SPHERE: 'sphere'
};

export const AOE_SIZES = {
  CIRCLE: [5, 10, 15, 20, 30, 40, 60],
  CONE: [15, 30, 60],
  CUBE: [5, 10, 15, 20, 30],
  LINE: [5, 10, 15, 20, 30, 60, 120],
  SPHERE: [5, 10, 15, 20, 30, 40]
};
